/**
 * @description Connection and endpoint checks (admins only): one GET with no body and no record data, to a
 * Connection's Named Credential URL or to an outbound event's exact endpoint (URL plus Path). For an Apex Auth
 * connection the Auth Class logs in first and adds its header, so a login problem is reported in plain words.
 * @group Integration Hub
 */
public with sharing class IntegrationHubEndpointCheck {

    /**
     * @description Result of a connection check.
     */
    public class CheckResult {
        /** @description True when the system answered (any HTTP status). */
        @AuraEnabled public Boolean reached = false;
        /** @description HTTP status of the answer, or null. */
        @AuraEnabled public Integer statusCode;
        /** @description Time taken in milliseconds. */
        @AuraEnabled public Long millis;
        /** @description What happened, in plain words. */
        @AuraEnabled public String message;
        /** @description Start of the system's reply body (up to 200 characters), or null. */
        @AuraEnabled public String reply;
    }

    /**
     * @description Checks that Salesforce can reach the connection's system: one GET to the Named Credential's URL,
     * with no body and no record data. Any HTTP answer means the system was reached; 401 or 403 point at the
     * credential, other answers are the system's own reply to its base URL. An Apex Auth connection runs its Auth
     * Class first; when it cannot log in, nothing is called and the reason is returned.
     * @param connectionId the Integration Connection
     * @return the result
     */
    @AuraEnabled
    public static CheckResult checkConnection(Id connectionId) {
        IntegrationHubMonitorController.requireAdmin();
        IH_Connection__c c = (IH_Connection__c) IntegrationHubData.queryFirst(
            'SELECT Id, Name, Named_Credential__c, Timeout_Seconds__c, Connection_Type__c, Auth_Class__c FROM IH_Connection__c WHERE Id = :id',
            new Map<String, Object>{ 'id' => connectionId });
        if (c == null || String.isBlank(c.Named_Credential__c)) {
            return notChecked('This connection has no Named Credential.');
        }
        HttpRequest req = getRequest('callout:' + c.Named_Credential__c, c.Timeout_Seconds__c);
        String loginProblem = login(req, c);
        if (loginProblem != null) {
            return notChecked(loginProblem);
        }
        CheckResult r = ping(req);
        if (r.reached) {
            r.message = authMessage(r.statusCode, c, checkMessage(r.statusCode));
        }
        return r;
    }

    /**
     * @description Checks the exact endpoint of an outbound event: one GET to its Named Credential URL plus its Path
     * ({recordId} and {transactionId} left empty), with no body and no record data. 404 means the Path is not
     * known there; 405 means the endpoint exists but takes another method, which is expected for a POST API.
     * @param eventId the Integration Event
     * @return the result
     */
    @AuraEnabled
    public static CheckResult checkEvent(Id eventId) {
        IntegrationHubMonitorController.requireAdmin();
        IH_Event__c ev = (IH_Event__c) IntegrationHubData.queryFirst('SELECT Event_Key__c, Direction__c, Path__c, Http_Method__c, '
            + 'Connection__r.Id, Connection__r.Name, Connection__r.Named_Credential__c, Connection__r.Timeout_Seconds__c, '
            + 'Connection__r.Connection_Type__c, Connection__r.Auth_Class__c FROM IH_Event__c WHERE Id = :id',
            new Map<String, Object>{ 'id' => eventId });
        String problem = eventProblem(ev);
        if (problem != null) {
            return notChecked(problem);
        }
        HttpRequest req = getRequest('callout:' + ev.Connection__r.Named_Credential__c
            + IntegrationHubRequestParts.resolvePath(ev.Path__c, '', ''), ev.Connection__r.Timeout_Seconds__c);
        String loginProblem = login(req, ev.Connection__r);
        if (loginProblem != null) {
            return notChecked(loginProblem);
        }
        CheckResult r = ping(req);
        if (r.reached) {
            r.message = authMessage(r.statusCode, ev.Connection__r, eventMessage(r.statusCode, ev.Http_Method__c));
        }
        return r;
    }

    /* Apex Auth: the Auth Class adds its login header to the check request. Null when fine, else the reason. */
    private static String login(HttpRequest req, IH_Connection__c conn) {
        IntegrationHub.AuthContext ctx = new IntegrationHub.AuthContext();
        ctx.request = req;
        ctx.connection = conn;
        String problem = IntegrationHubConnectionAuth.runAuthClass(ctx);
        return problem == null ? null : 'Not checked: the login of this Apex Auth connection failed. ' + problem;
    }

    /**
     * @description For an Apex Auth connection, a 401 or 403 points at the Auth Class instead of the Named Credential.
     * @param code the HTTP status
     * @param conn the connection
     * @param otherwise the message for any other case
     * @return the message
     */
    @TestVisible
    private static String authMessage(Integer code, IH_Connection__c conn, String otherwise) {
        if (!IntegrationHubConnectionAuth.isApexAuth(conn) || (code != 401 && code != 403)) {
            return otherwise;
        }
        return 'Reached, but the system refused the login that Auth Class ' + conn.Auth_Class__c + ' added (HTTP ' + code
            + '). Check the class and the login Named Credential it uses.';
    }

    @TestVisible
    private static String eventProblem(IH_Event__c ev) {
        if (ev == null) {
            return 'Event not found.';
        }
        if (ev.Direction__c == IntegrationHub.INBOUND) {
            return 'Inbound events are called by the other system; there is no endpoint to check from here.';
        }
        if (ev.Connection__r == null || String.isBlank(ev.Connection__r.Named_Credential__c)) {
            return 'This event has no Connection with a Named Credential.';
        }
        return String.isBlank(ev.Path__c) ? 'This event has no Path.' : null;
    }

    private static CheckResult notChecked(String message) {
        CheckResult r = new CheckResult();
        r.message = message;
        return r;
    }

    private static HttpRequest getRequest(String endpoint, Decimal timeoutSeconds) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint(endpoint);
        req.setMethod('GET');
        req.setTimeout(timeoutSeconds == null ? 30000 : Math.min(timeoutSeconds.intValue(), 120) * 1000);
        return req;
    }

    private static CheckResult ping(HttpRequest req) {
        CheckResult r = new CheckResult();
        Long started = System.currentTimeMillis();
        try {
            HttpResponse res = new Http().send(req);
            r.statusCode = res.getStatusCode();
            r.reached = true;
            r.reply = replyStart(res.getBody());
        } catch (Exception e) {
            r.message = 'Not reached: ' + e.getMessage();
        }
        r.millis = System.currentTimeMillis() - started;
        return r;
    }

    @TestVisible
    private static String replyStart(String body) {
        return String.isBlank(body) ? null : body.normalizeSpace().abbreviate(200);
    }

    @TestVisible
    private static String checkMessage(Integer code) {
        if (code == 401 || code == 403) {
            return 'Reached, but the system refused the credential (HTTP ' + code + '). Check the Named Credential and its principal.';
        }
        return 'Reached: the system answered HTTP ' + code + '.';
    }

    @TestVisible
    private static String eventMessage(Integer code, String method) {
        if (code == 404) {
            return 'Reached the system, but it answered 404 for this Path. Read its reply below: a wrong Path, or a system '
                + 'that answers 404 to a GET on a POST-only API.';
        }
        if (code == 405) {
            return 'Endpoint found: it does not take GET (HTTP 405), as expected for a ' + (method == null ? 'POST' : method) + ' API.';
        }
        return checkMessage(code);
    }
}
